command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="2d38f480998e522e4cfbe2b8a3ca2fef68ff6637"
$candidate="f134d4794615fb088675bd804621b974bb4428c8"
$branch="work/removable-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "removable visual fetch failed"}
$observedMain=(& git rev-parse refs/remotes/origin/main).Trim()
if($observedMain -ne $main){throw "main moved before removable visual validation"}
$observedCandidate=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
if($observedCandidate -ne $candidate){throw "removable visual candidate ref mismatch"}
$dirty=@(& git status --porcelain=v1)
if($dirty.Count -ne 0){
  $dirty | ForEach-Object { Write-Host ("UNEXPECTED_WORKTREE="+$_) }
  throw "persistent checkout is not clean"
}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "candidate checkout failed"}
& .\build.bat Release
if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}
$baseline=Join-Path $repo "logs\network-visual\network-visual-before.bmp"
$evidence=Join-Path $repo "logs\remote-evidence"
New-Item -ItemType Directory -Force -Path $evidence | Out-Null
if(Test-Path -LiteralPath $baseline -PathType Leaf){
  Copy-Item -LiteralPath $baseline -Destination (Join-Path $evidence "removable-visual-before.bmp") -Force
  $hash=(Get-FileHash -Algorithm SHA256 -LiteralPath $baseline).Hash.ToLowerInvariant()
  Write-Host "REMOVABLE_VISUAL_BASELINE_REUSED=$hash"
}else{
  Write-Host "REMOVABLE_VISUAL_BASELINE_REUSED=NOT_AVAILABLE"
}
& python -X utf8 tests\winui\test_network_visual_gui.py --configuration Release --capture after --force-removable-detail
if($LASTEXITCODE -ne 0){throw "focused removable visual GUI failed"}
$after=Join-Path $repo "logs\network-visual\network-visual-after.bmp"
if(-not (Test-Path -LiteralPath $after -PathType Leaf)){throw "removable visual AFTER capture missing"}
Copy-Item -LiteralPath $after -Destination (Join-Path $evidence "removable-visual-after.bmp") -Force
$afterHash=(Get-FileHash -Algorithm SHA256 -LiteralPath $after).Hash.ToLowerInvariant()
Write-Host "REMOVABLE_VISUAL_AFTER_SHA256=$afterHash"
$physical=@(Get-CimInstance Win32_LogicalDisk -Filter "DriveType=2" -ErrorAction SilentlyContinue)
if($physical.Count -eq 0){
  Write-Host "REMOVABLE_VISUAL_PHYSICAL_USB=NOT_RUN_NO_DEVICE"
}else{
  Write-Host "REMOVABLE_VISUAL_PHYSICAL_USB=NOT_RUN_NO_TEST_OWNERSHIP"
}
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to return canonical checkout to main"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward canonical main checkout"}
Write-Host "REMOVABLE_SHELL_VISUAL_VALIDATION=PASS"
